from __future__ import annotations

"""Causal explanation/evidence layer for Mobile V1 primary decisions.

The UI must answer why THIS decision/value was chosen. It never substitutes generic
policy prose for missing evidence; insufficient evidence is called out explicitly.
"""

_STYLE = r'''
<style id="yipmanV1AllDecisionEvidenceStyle">
.v1-detail-decision{cursor:pointer;touch-action:manipulation;position:relative;padding-right:46px!important}.v1-detail-decision::after{content:'WHY ›';position:absolute;right:13px;top:15px;color:#75b9eb;font-size:8px;font-weight:1000}.v1-decision-evidence{margin:0 0 9px;border:1px solid #314453;border-radius:14px;background:#101a22;overflow:hidden}.v1-decision-evidence>summary{list-style:none;cursor:pointer;padding:11px 12px;font-size:11px;font-weight:1000;color:#e8f1f7;display:flex;justify-content:space-between}.v1-decision-evidence>summary::-webkit-details-marker{display:none}.v1-decision-evidence>summary span{color:#77b8e7;font-size:9px}.v1-decision-evidence[open]>summary{border-bottom:1px solid #2a3b47}.v1-decision-evidence-body{padding:10px 12px}.v1-decision-section{margin-bottom:12px}.v1-decision-section h4{margin:0 0 5px;color:#8194a3;font-size:8px;font-weight:1000;letter-spacing:.05em}.v1-decision-section p{margin:0;color:#c0cbd3;font-size:11px;line-height:1.45}.v1-decision-grid{display:grid;grid-template-columns:minmax(0,1fr) auto;gap:6px 10px;font-size:10px}.v1-decision-grid b{color:#8193a1}.v1-decision-grid span{text-align:right;color:#eef4f7;font-weight:1000}.v1-decision-missing{border:1px solid #735d25;background:#241f13;border-radius:10px;padding:9px;color:#e3c36d!important;font-weight:800}.v1-decision-flow{font-weight:900;color:#eef4f7!important}.v1-decision-source{color:#8ba0af!important;font-size:9px!important}
</style>'''

_SCRIPT = r'''
<script id="yipmanV1AllDecisionEvidenceScript">
(()=>{'use strict';
 const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const txt=(r,s)=>String(r?.querySelector(s)?.textContent||'').trim();
 const metric=(r,label)=>{for(const el of r.querySelectorAll('.v1-detail-metrics>div,.v1-force-order-cell')){const k=txt(el,'b').toUpperCase();if(k.includes(label))return txt(el,'span')||txt(el,'strong')}return''};
 const identity=(r,label)=>{for(const el of r.querySelectorAll('.v1-detail-id>div'))if(txt(el,'b').toUpperCase().includes(label))return txt(el,'span');return''};
 const money=v=>{const n=parseFloat(String(v||'').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:null};
 const num=v=>{const n=parseFloat(String(v||'').replace(/[^0-9.-]/g,''));return Number.isFinite(n)?n:null};
 const actionPrice=a=>money((String(a).match(/\$\s*([0-9.]+)/)||[])[1]);
 function typeOf(a,s){s=(a+' '+s).toUpperCase();if(/^ORDER\b|^NO ORDER\b/.test(s))return'ORDER';if(s.includes('CLEAR'))return'CLEARANCE';if(s.includes('TPR-FRESH')||s.includes('FRESHNESS'))return'TPR_FRESH';if(s.includes('TPR'))return'TPR_GP';if(s.includes('DUMP')||s.includes('PI')||s.includes('STOCK'))return'INVENTORY';if(s.includes('REG')||s.includes('PRICE'))return'PRICE';return'GENERAL'}
 function build(type,action,body){const v={family:identity(body,'FAMILY'),upc:identity(body,'UPC'),oh:metric(body,'EFFECTIVE OH')||txt(body,'.v1-detail-oh strong'),price:metric(body,'CURRENT PRICE'),suggested:metric(body,'SUGGESTED PRICE'),cost:metric(body,'CURRENT COST'),sales:metric(body,'7D SALES'),avg:metric(body,'7D AVG'),dos:metric(body,'DOS'),delivery:metric(body,'DELIVERY'),next:metric(body,'NEXT DELIVERY'),proj:metric(body,'PROJECTED OH'),coverage:metric(body,'COVERAGE USE')};v.suggested=v.suggested||((actionPrice(action)!=null)?'$'+actionPrice(action).toFixed(2):'');const cp=money(v.price),sp=money(v.suggested),c=money(v.cost),av=num(v.avg),oh=num(v.oh);let trigger='',comparison='',math='',decision='',success='',missing=[];
  if(type==='TPR_GP'||type==='PRICE'){
   trigger='The system is proposing a price test/change because the current price is not being treated as the established best GP$/day sweet spot.';
   if(cp!=null&&sp!=null&&c!=null){const curMargin=cp-c,newMargin=sp-c,be=curMargin>0&&newMargin>0?curMargin/newMargin:null;comparison=`Current $${cp.toFixed(2)} gives $${curMargin.toFixed(2)} gross profit per unit/lb before shrink. Proposed $${sp.toFixed(2)} gives $${newMargin.toFixed(2)}.`;math=be?`To match current GP$/day, volume at $${sp.toFixed(2)} must be at least ${be.toFixed(2)}× current volume (${((be-1)*100).toFixed(1)}% ${be>=1?'more':'less'}).`:'Margin break-even cannot be calculated.'}else missing.push('current price + suggested price + cost');
   if(av!=null&&cp!=null&&sp!=null&&c!=null){const cur=(cp-c)*av,need=cur/Math.max(.0001,sp-c);math+=` At displayed ${av.toFixed(2)}/day, current GP$/day is about $${cur.toFixed(2)}; $${sp.toFixed(2)} needs ≥${need.toFixed(2)}/day to beat it.`}else missing.push('actual current-price velocity / comparable tested-price velocity');
   missing.push('historical tested-price events and their GP$/day','Company A/B/C constraint values when applicable');decision=`$${sp!=null?sp.toFixed(2):'—'} is the server-selected next price, but this screen can only fully justify that exact step when comparable price-history evidence is exposed.`;success=sp!=null&&cp!=null&&c!=null&&av!=null?`Success: observed volume at $${sp.toFixed(2)} exceeds the break-even rate and produces GP$/day above the current-price baseline; then evaluate promotion to REG sweet spot.`:'Success criteria require baseline velocity and proposed-price observed velocity.';
  }else if(type==='TPR_FRESH'||type==='CLEARANCE'){
   trigger=type==='TPR_FRESH'?'Stock is entering the freshness sell-through intervention window.':'Stock is at clearance-level freshness/expiration risk.';comparison=`Effective OH ${v.oh||'not exposed'} versus recent velocity ${v.avg||'not exposed'}/day and stock-days ${v.dos||'not exposed'}.`;if(oh!=null&&av!=null&&av>0)math=`At the displayed velocity, ${oh.toFixed(1)} stock requires about ${(oh/av).toFixed(1)} selling days. The price action must raise sell-through enough to clear the at-risk stock by the applicable freshness threshold.`;else missing.push('Effective OH and recent velocity');missing.push('current stock age/DOH and exact threshold date','price-response history at comparable markdowns');decision=`Use ${v.suggested||action} as the server sell-through action; the exact price needs price-response evidence to be numerically auditable.`;success='Success: at-risk stock reaches the sell-through target by the freshness/expiration threshold with less dumping.';
  }else if(type==='ORDER'){
   trigger=action.toUpperCase().startsWith('NO ORDER')?'Projected stock covers the selected delivery window.':'Projected stock does not cover expected demand for the selected delivery window.';comparison=`Effective OH ${v.oh||'not exposed'}; projected OH ${v.proj||'not exposed'}; coverage demand ${v.coverage||'not exposed'}; delivery ${v.delivery||'not exposed'} → next ${v.next||'not exposed'}.`;if(v.proj&&v.coverage)math=`Order need is driven by coverage demand minus projected available stock, then freshness/UOM/pack constraints and rounding are applied.`;else missing.push('projected OH and coverage-window demand');decision=action;success='Success: projected stock covers demand through the day before next delivery without avoidable overstock/freshness risk.';
  }else{trigger='The backend raised this operational action from the current item state.';comparison='Only evidence exposed in this Action Detail can be audited here.';missing.push('decision-specific intermediate inputs');decision=action;success='Success criteria must be supplied by the decision engine for this action type.'}
  const ev=[['Family',v.family],['UPC',v.upc],['Effective OH',v.oh],['Current price',v.price],['Suggested price',v.suggested],['Current cost',v.cost],['7D sales',v.sales],['7D avg',v.avg],['DOS / stock days',v.dos],['Projected OH',v.proj],['Coverage use',v.coverage]].filter(x=>x[1]);return{trigger,comparison,math,decision,success,missing:[...new Set(missing)],ev}}
 function apply(){const overlay=document.getElementById('v1DetailOverlay'),body=document.getElementById('v1DetailBody');if(!overlay?.classList.contains('open')||!body)return;const card=body.querySelector('.v1-detail-decision');if(!card)return;const action=txt(card,'strong'),subtitle=txt(card,'p'),sig=action+'|'+identity(body,'FAMILY')+'|'+identity(body,'UPC');if(body.dataset.causalDecisionEvidence===sig)return;body.dataset.causalDecisionEvidence=sig;body.querySelectorAll('.v1-decision-evidence').forEach(x=>x.remove());const d=build(typeOf(action,subtitle),action,body),box=document.createElement('details');box.className='v1-decision-evidence';box.open=true;const grid='<div class="v1-decision-grid">'+d.ev.map(([k,v])=>'<b>'+esc(k)+'</b><span>'+esc(v)+'</span>').join('')+'</div>';const missing=d.missing.length?'<p class="v1-decision-missing">Cannot fully prove this exact decision yet. Missing evidence: '+esc(d.missing.join('; '))+'.</p>':'';box.innerHTML='<summary>WHY THIS EXACT DECISION <span>tap to collapse</span></summary><div class="v1-decision-evidence-body"><section class="v1-decision-section"><h4>1 · TRIGGER</h4><p>'+esc(d.trigger)+'</p></section><section class="v1-decision-section"><h4>2 · COMPARISON</h4><p>'+esc(d.comparison)+'</p></section><section class="v1-decision-section"><h4>3 · MATH</h4><p>'+esc(d.math||'Required numerical inputs are not exposed.')+'</p></section><section class="v1-decision-section"><h4>4 · EVIDENCE</h4>'+grid+'</section><section class="v1-decision-section"><h4>5 · WHY THIS DECISION</h4><p class="v1-decision-flow">'+esc(d.decision)+'</p>'+missing+'</section><section class="v1-decision-section"><h4>6 · SUCCESS CRITERIA</h4><p>'+esc(d.success)+'</p></section><section class="v1-decision-section"><h4>SOURCE / LIMITATION</h4><p class="v1-decision-source">Uses only values exposed by the live FULL MYSQL Action Detail. The UI does not invent historical tests, velocity, DOH, company constraints, or backend intermediate calculations.</p></section></div>';card.insertAdjacentElement('afterend',box);card.onclick=()=>box.open=!box.open}
 let q=false;const kick=()=>{if(q)return;q=true;requestAnimationFrame(()=>{q=false;apply()})};new MutationObserver(kick).observe(document.documentElement,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});document.addEventListener('click',()=>setTimeout(kick,20),true);setInterval(kick,1200);
})();
</script>'''

def polish_all_decision_evidence_html(html: str) -> str:
    if 'yipmanV1AllDecisionEvidenceStyle' in html:return html
    return html.replace('</head>',_STYLE+'</head>',1).replace('</body>',_SCRIPT+'</body>',1)
